      PregFaqPart(PregFaqSection.perspective, '', [
        'It\'s a strange thing to picture, guiding a baby by hand through your belly, but it\'s a well practised, carefully monitored procedure that many doctors perform routinely and safely.',
      ], []),
      PregFaqPart(PregFaqSection.takeaways, '', [], [
        'External Cephalic Version (ECV) attempts to turn a breech baby head-down by hand.',
        'Usually offered around 36 to 37 weeks, done in a hospital setting.',
        'Your baby\'s heartbeat is monitored continuously throughout.',
        'Only performed where an emergency C-section is immediately available.',
